#include "stock_native_detached_turret_snapshot.hpp"
#include "stock_native_bot_python.hpp"
#include "stock_native_wire_value.hpp"
#include <algorithm>

namespace stock_native_detached_turret {
namespace {
namespace p=stock_native_bot_python;
namespace w=stock_native_wire_value;
using w::Value;
using w::Kind;
double bounded(const Value&value,double low,double high){const auto v=w::scalar(value);if(v<low||v>high)throw p::Error("Detached turret number outside wire envelope");return v;}
std::int64_t integer(const Value&value,std::int64_t low=0){const auto n=w::wide(value);if(n<low||n>2147483647)throw p::Error("Detached turret integer outside wire envelope");return n;}
// p::numbers<3>: a three-element sequence of finite numbers.
Point vector(const Value&raw,double bound){const auto&value=raw.resolved();if(w::size(value)!=3)throw p::Error("Native Bot vector width mismatch");Point result;for(unsigned i=0;i<3;++i){result[i]=w::scalar(value.array[i]);if(std::abs(result[i])>bound)throw p::Error("Detached turret vector outside wire envelope");}return result;}
Point point(const Value&object,const char*name,double bound){return vector(object.resolved().get(name),bound);}
Point nativePoint(PyObject*object){if(PyTuple_Check(object)||PyList_Check(object))return p::numbers<3>(object);Point result;for(unsigned i=0;i<3;++i){auto v=p::value(object,i==0?"x":i==1?"y":"z");result[i]=p::scalar(v.get());}return result;}
bool bit(const Value&object,const char*name){const auto&value=object.resolved().get(name).resolved();if(value.kind!=Kind::Boolean)throw p::Error("Detached turret boolean is invalid");return value.boolean;}
Owner owner(const std::string&kind,std::int64_t id){if(kind!="bot"&&kind!="player")throw p::Error("Detached turret actor kind is invalid");return {kind=="player",id};}
Owner actorKey(const std::string&key){const auto split=key.find(':');if(split==std::string::npos||key.find(':',split+1)!=std::string::npos)throw p::Error("Detached turret actor key is invalid");std::size_t used=0;const auto suffix=key.substr(split+1);const auto id=std::stoll(suffix,&used);if(used!=suffix.size()||id<1||id>2147483647)throw p::Error("Detached turret actor id is invalid");return owner(key.substr(0,split),id);}
std::string actorKey(Owner key){return std::string(key.human?"player:":"bot:")+std::to_string(key.id);}
Checkpoint checkpoint(const Value&raw){const auto&row=raw.resolved();if(w::size(row)!=8)throw p::Error("Detached turret checkpoint width is invalid");Checkpoint out;out.player=actorKey(w::string(row.array[0]));out.sequence=integer(row.array[1],1);for(unsigned i=0;i<6;++i)(i<3?out.linear[i]:out.angular[i-3])=bounded(row.array[i+2],-1.e12,1.e12);return out;}
std::vector<Checkpoint> checkpoints(const Value&raw){const auto&rows=raw.resolved();if(w::size(rows)>30)throw p::Error("Detached turret checkpoint list is too large");std::vector<Checkpoint> out;std::set<Owner> unique;for(const auto&row:rows.array){auto result=checkpoint(row);if(!unique.insert(result.player).second)throw p::Error("Detached turret checkpoint actor is repeated");out.push_back(result);}return out;}
Frame frame(const Value&raw){const auto&object=raw.resolved();if(object.kind!=Kind::Object)throw p::Error("Detached turret body is invalid");Frame out;out.position=point(object,"position",5000.);out.attitude=point(object,"attitude",1000.);out.centre=point(object,"centre",5000.);out.velocity=point(object,"velocity",3000.);out.angular_velocity=point(object,"angular_velocity",1000.);out.grounded=bit(object,"grounded");out.sleeping=bit(object,"sleeping");out.impact_serial=integer(object.get("impact_serial"));out.acknowledgements=checkpoints(object.get("acks"));const auto&impact=object.get("impact").resolved();if(impact.kind!=Kind::Null){Impact hit;hit.point=point(impact,"point",5000.);hit.normal=point(impact,"normal",1.);hit.velocity=point(impact,"velocity",3000.);hit.energy=bounded(impact.get("energy"),0.,13500000.);out.impact=hit;}return out;}
// Stock getBoundingBox returns (minimum, maximum, radius). The original
// component_bounds consumer reads the first two entries only.
stock_native_bot_turret::Component componentBounds(PyObject*object){stock_native_bot_turret::Component out;auto tester=p::value(object,"hitTester"),bounds=p::value(tester.get(),"bbox");if(p::size(bounds.get())<2)throw p::Error("Detached turret component bounds are unavailable");auto low=p::item(bounds.get(),0),high=p::item(bounds.get(),1);out.bounds.minimum=nativePoint(low.get());out.bounds.maximum=nativePoint(high.get());for(unsigned i=0;i<3;++i)if(out.bounds.minimum[i]>=out.bounds.maximum[i])throw p::Error("Detached turret component bounds are empty");return out;}
stock_native_bot_turret::Component component(PyObject*object){auto tester=p::value(object,"hitTester"),hit=p::value(tester.get(),"localHitTest");if(!PyCallable_Check(hit.get()))throw p::Error("Detached turret component tester is unavailable");return componentBounds(object);}
Value packedCheckpoint(const Checkpoint&c){auto out=w::array();out.array.push_back(w::text(actorKey(c.player)));out.array.push_back(w::integer(c.sequence));for(auto v:c.linear)out.array.push_back(w::number(v));for(auto v:c.angular)out.array.push_back(w::number(v));return out;}
Value packedFrame(const Frame&f){auto out=w::object();auto&o=out.object;o["position"]=w::numbers(f.position);o["attitude"]=w::numbers(f.attitude);o["centre"]=w::numbers(f.centre);o["velocity"]=w::numbers(f.velocity);o["angular_velocity"]=w::numbers(f.angular_velocity);o["grounded"]=w::boolean(f.grounded);o["sleeping"]=w::boolean(f.sleeping);o["impact_serial"]=w::integer(f.impact_serial);auto acks=w::array();for(const auto&c:f.acknowledgements)acks.array.push_back(packedCheckpoint(c));o["acks"]=std::move(acks);Value impact;if(f.impact){impact=w::object();auto&i=impact.object;i["point"]=w::numbers(f.impact->point);i["normal"]=w::numbers(f.impact->normal);i["velocity"]=w::numbers(f.impact->velocity);i["energy"]=w::number(f.impact->energy);}o["impact"]=std::move(impact);return out;}
}
bool readRow(const Value&raw,Row&output,std::string*error){try{const auto&object=raw.resolved();Row out;const auto&sequence=object.get("motion_seq").resolved();const auto&flight=object.get("flight").resolved();out.owner=owner(w::string(object.get("actor_kind")),integer(object.get("actor_id"),1));out.created_time_ms=integer(object.get("created_time_ms"));out.attitude=point(object,"attitude",1000.);out.spin=point(object,"spin",1000.);if(sequence.kind!=Kind::Null){out.motion_sequence=integer(sequence,1);const auto&support=object.get("support_key").resolved();out.motion_time_ms=integer(object.get("motion_time_ms"));if(support.kind!=Kind::Null)out.support=actorKey(w::string(support));}
    auto&f=out.flight;f.origin=point(flight,"origin",5000.);f.velocity=point(flight,"velocity",3000.);f.rest=point(flight,"rest",5000.);f.impact_velocity=point(flight,"impact_velocity",3000.);const auto&contact=flight.get("contact").resolved(),&segments=flight.get("segments").resolved(),&rest_attitude=flight.get("rest_attitude").resolved();f.duration=bounded(flight.get("duration"),0.,8.);f.energy=bounded(flight.get("energy"),0.,13500000.);f.landed=bit(flight,"landed");if(contact.kind!=Kind::Null)f.contact=vector(contact,5000.);if(f.landed!=bool(f.contact))throw p::Error("Detached turret landing outcome is invalid");if(rest_attitude.kind!=Kind::Null)f.rest_attitude=vector(rest_attitude,1000.);if(flight.kind==Kind::Object&&flight.object.count("body"))f.body=frame(flight.get("body"));const auto count=w::size(segments);if(count<1||count>4)throw p::Error("Detached turret segment count is invalid");for(const auto&value:segments.array){const auto&segment_raw=value.resolved();Segment segment;segment.origin=point(segment_raw,"origin",5000.);segment.velocity=point(segment_raw,"velocity",3000.);segment.start=bounded(segment_raw.get("start"),0.,8.);segment.duration=bounded(segment_raw.get("duration"),0.,8.);if(segment.start+segment.duration>8.+1.e-9)throw p::Error("Detached turret segment exceeds flight window");f.segments.push_back(segment);}output=std::move(out);return true;}catch(const std::exception&e){if(error)*error=e.what();return false;}}
bool readComponents(PyObject*descriptor,std::vector<Component>&output){try{auto turret=p::value(descriptor,"turret"),gun=p::value(descriptor,"gun"),mount=p::value(turret.get(),"gunPosition");std::vector<Component> out;for(auto*object:{turret.get(),gun.get()}){Component part;part.geometry=component(object);auto weight=p::value(object,"weight");part.mass=p::scalar(weight.get());if(part.mass<=0.)throw p::Error("Detached component weight must be positive");out.push_back(part);}out[1].geometry.offset=nativePoint(mount.get());properties(out);output=std::move(out);return true;}catch(const std::exception&e){if(!PyErr_Occurred())PyErr_SetString(PyExc_ValueError,e.what());return false;}}
bool readVehicleGeometry(PyObject*descriptor,VehicleGeometry&output){try{VehicleGeometry out;auto chassis=p::value(descriptor,"chassis"),hull=p::value(descriptor,"hull"),turret=p::value(descriptor,"turret"),gun=p::value(descriptor,"gun"),hull_mount=p::value(chassis.get(),"hullPosition"),mounts=p::value(hull.get(),"turretPositions"),gun_mount=p::value(turret.get(),"gunPosition");out.chassis=componentBounds(chassis.get());out.hull=componentBounds(hull.get());out.turret=componentBounds(turret.get());out.gun=componentBounds(gun.get());out.hull.offset=nativePoint(hull_mount.get());auto turret_mount=p::item(mounts.get(),0);out.turret_mount=nativePoint(turret_mount.get());for(unsigned i=0;i<3;++i)out.turret_mount[i]+=out.hull.offset[i];out.gun_mount=nativePoint(gun_mount.get());output=std::move(out);return true;}catch(const std::exception&e){if(!PyErr_Occurred())PyErr_SetString(PyExc_ValueError,e.what());return false;}}
bool readLaunchGeometry(PyObject*descriptor,LaunchInput&output){try{auto chassis=p::value(descriptor,"chassis"),hull=p::value(descriptor,"hull"),turret=p::value(descriptor,"turret"),gun=p::value(descriptor,"gun"),hull_mount=p::value(chassis.get(),"hullPosition"),mounts=p::value(hull.get(),"turretPositions");auto ring=p::item(mounts.get(),0);auto result=output;const auto hp=nativePoint(hull_mount.get()),tp=nativePoint(ring.get());for(unsigned i=0;i<3;++i)result.mount[i]=hp[i]+tp[i];const auto turret_geometry=component(turret.get());component(gun.get());result.clearance=std::max(0.,-turret_geometry.bounds.minimum[1]);result.geometry_ready=true;result.exploded_models=true;for(auto*object:{turret.get(),gun.get()}){auto models=p::value(object,"models"),exploded=p::value(models.get(),"exploded");if(exploded.get()==Py_None)result.exploded_models=false;}output=result;return true;}catch(const std::exception&e){if(!PyErr_Occurred())PyErr_SetString(PyExc_ValueError,e.what());return false;}}
bool readPlayerImpulses(const Value&player,std::vector<PlayerImpulse>&output,std::string*error){try{return readPlayerImpulses(integer(player.resolved().get("id"),1),&player.resolved().get("turret_pushes"),output,error);}catch(const std::exception&e){if(error)*error=e.what();return false;}}
bool readPlayerImpulses(std::int64_t player,const Value*pushes,std::vector<PlayerImpulse>&output,std::string*error){try{if(player<1||player>2147483647)throw p::Error("Detached turret integer outside wire envelope");const Owner source{true,player};if(!pushes||pushes->resolved().kind==Kind::Null)return true;auto values=checkpoints(*pushes);std::vector<PlayerImpulse> out;for(auto&c:values){const auto target=c.player;c.player=source;out.push_back({target,c});}output.insert(output.end(),out.begin(),out.end());return true;}catch(const std::exception&e){if(error)*error=e.what();return false;}}
Value packRow(const Row&r){auto out=w::object();auto&o=out.object;o["actor_kind"]=w::text(r.owner.human?"player":"bot");o["actor_id"]=w::integer(r.owner.id);o["attitude"]=w::numbers(r.attitude);o["spin"]=w::numbers(r.spin);o["created_time_ms"]=w::integer(r.created_time_ms);if(r.motion_sequence){o["motion_seq"]=w::integer(r.motion_sequence);o["motion_time_ms"]=w::integer(r.motion_time_ms);o["support_key"]=r.support?w::text(actorKey(*r.support)):Value();}const auto&f=r.flight;auto flight=w::object();auto&g=flight.object;g["origin"]=w::numbers(f.origin);g["velocity"]=w::numbers(f.velocity);g["rest"]=w::numbers(f.rest);g["impact_velocity"]=w::numbers(f.impact_velocity);g["duration"]=w::number(f.duration);g["energy"]=w::number(f.energy);g["landed"]=w::boolean(f.landed);g["contact"]=f.contact?w::numbers(*f.contact):Value();if(f.rest_attitude)g["rest_attitude"]=w::numbers(*f.rest_attitude);if(f.body)g["body"]=packedFrame(*f.body);auto segments=w::array();for(const auto&s:f.segments){auto segment=w::object();auto&q=segment.object;q["origin"]=w::numbers(s.origin);q["velocity"]=w::numbers(s.velocity);q["start"]=w::number(s.start);q["duration"]=w::number(s.duration);segments.array.push_back(std::move(segment));}g["segments"]=std::move(segments);o["flight"]=std::move(flight);return out;}

}
